1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Step = {
25	  op: string;
26	  items: Item[];
27	};
28	
29	export type Item = { type: string } & Record<string, unknown>;
30	
31	export type Result = { premium: number };
32	
33	export type ScenarioOutcome = { results: Result[] };
34	
35	/** A block is exactly this many items of one and the same type. */
36	const BLOCK_SIZE = 3;
37	
38	/** Special base premium charged for a complete block, instead of the per-item sum. */
39	const BLOCK_BASE_PREMIUM = 60;
40	
41	/** Number of items of each type on a policy. */
42	const countByType = (items: Item[]): Map<string, number> => {
43	  const counts = new Map<string, number>();
44	  for (const item of items) {
45	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
46	  }
47	  return counts;
48	};
49	
50	/** Base premium of a single item of the given type, before block pricing or surcharge. */
51	const basePremiumOfType = (type: string): number => BASE_PREMIUM_BY_TYPE[type];
52	
53	/** Base premium for all items of one and the same type. */
54	const groupBasePremium = (type: string, count: number): number =>
55	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
56	
57	/** Base premium of a policy covering the given items. */
58	const calculateBasePremium = (items: Item[]): number =>
59	  [...countByType(items)].reduce(
60	    (total, [type, count]) => total + groupBasePremium(type, count),
61	    0,
62	  );
63	
64	/** Risk surcharge charged on the base premium of a cursed item. */
65	const CURSE_RATE = 0.5;
66	
67	/** Enchantment level from which an item counts as highly enchanted. */
68	const HIGH_ENCHANTMENT_LEVEL = 5;
69	
70	/** Risk surcharge charged on the base premium of a highly enchanted item. */
71	const HIGH_ENCHANTMENT_RATE = 0.3;
72	
73	/** True when the item is enchanted strongly enough to attract the surcharge. */
74	const isHighlyEnchanted = (item: Item): boolean =>
75	  typeof item.enchantment === "number" &&
76	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
77	
78	/** Combined rate of the surcharges an item attracts. */
79	const itemSurchargeRate = (item: Item): number => {
80	  const curseRate = item.cursed ? CURSE_RATE : 0;
81	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
82	  return curseRate + enchantmentRate;
83	};
84	
85	/** Surcharges an individual item attracts, charged on its own base premium. */
86	const itemSurcharges = (item: Item): number =>
87	  basePremiumOfType(item.type) * itemSurchargeRate(item);
88	
89	/** Surcharges that attach to individual items rather than to the whole policy. */
90	const calculateItemSurcharges = (items: Item[]): number =>
91	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
92	
93	/** Years of business from which a customer counts as long-standing. */
94	const LOYALTY_YEARS = 2;
95	
96	/** Discount a long-standing customer receives on the policy base premium. */
97	const LOYALTY_RATE = -0.2;
98	
99	/** True when the customer has been with MHPCO long enough to earn the discount. */
100	const isLongStanding = (customer: Customer): boolean =>
101	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
102	
103	/** Discount on every contract after the customer's first. */
104	const FOLLOW_UP_RATE = -0.15;
105	
106	/**
107	 * Rates that attach to the policy as a whole. Each applies to the policy base
108	 * premium; positive rates are surcharges, negative ones discounts.
109	 */
110	const POLICY_RATES: {
111	  rate: number;
112	  applies: (customer: Customer, previousContracts: number) => boolean;
113	}[] = [
114	  { rate: FIRST_INSURANCE_RATE, applies: () => true },
115	  { rate: LOYALTY_RATE, applies: isLongStanding },
116	  { rate: FOLLOW_UP_RATE, applies: (_, previousContracts) => previousContracts > 0 },
117	];
118	
119	/** Net of every policy-wide rate the customer qualifies for. */
120	const policyRate = (customer: Customer, previousContracts: number): number =>
121	  POLICY_RATES.reduce(
122	    (total, { rate, applies }) =>
123	      applies(customer, previousContracts) ? total + rate : total,
124	    0,
125	  );
126	
127	/** Net policy-wide adjustment, charged on the policy base premium. */
128	const calculatePolicyAdjustment = (
129	  policyBasePremium: number,
130	  customer: Customer,
131	  previousContracts: number,
132	): number => policyBasePremium * policyRate(customer, previousContracts);
133	
134	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
135	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
136	
137	/** Price a policy covering the given items. */
138	const quotePremium = (
139	  items: Item[],
140	  customer: Customer,
141	  previousContracts: number,
142	): number => {
143	  const policyBasePremium = calculateBasePremium(items);
144	  const itemSurcharges = calculateItemSurcharges(items);
145	  const policyAdjustment = calculatePolicyAdjustment(
146	    policyBasePremium,
147	    customer,
148	    previousContracts,
149	  );
150	  return roundPremiumUp(
151	    policyBasePremium + itemSurcharges + policyAdjustment + PROCESSING_FEE,
152	  );
153	};
154	
155	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
156	  results: scenario.steps.map((step, previousContracts) => ({
157	    premium: quotePremium(step.items, scenario.customer, previousContracts),
158	  })),
159	});
