export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  // Steps are priced in order, so a step's index is the number of contracts
  // the customer already holds when that step is quoted.
  results: scenario.steps.map((step, stepIndex) => ({
    premium: quotePremium(step.items, scenario.customer, stepIndex),
  })),
});

